-- Valetax: SQL lengkap joined users dan import report Telegram
-- Sumber report: messages.html dan messages2.html
-- Jalankan satu kali pada database bot_db melalui phpMyAdmin.
-- File ini menambahkan tracking delivery admin lalu mengimpor report yang
-- berhasil dicocokkan secara aman dengan user_progress.
--
-- Catatan: 611 user unik cocok aman berdasarkan nama + user_progress.user_id.
-- Report ambigu/tidak ditemukan tidak dipaksakan masuk agar ID Telegram tidak salah.

SET SQL_MODE = "NO_AUTO_VALUE_ON_ZERO";
SET time_zone = "+07:00";

-- [1] Tambah kolom tracking delivery admin
ALTER TABLE `user_progress`
    ADD COLUMN `admin_notified_at` DATETIME NULL DEFAULT NULL AFTER `completed_at`,
    ADD COLUMN `admin_forwarded_at` DATETIME NULL DEFAULT NULL AFTER `admin_notified_at`,
    ADD COLUMN `admin_sent_at` DATETIME NULL DEFAULT NULL AFTER `admin_forwarded_at`,
    ADD COLUMN `admin_message_id` BIGINT NULL DEFAULT NULL AFTER `admin_sent_at`,
    ADD COLUMN `admin_forward_message_id` BIGINT NULL DEFAULT NULL AFTER `admin_message_id`;

ALTER TABLE `user_progress`
    ADD KEY `idx_admin_sent_at` (`admin_sent_at`),
    ADD KEY `idx_admin_delivery` (`completed_at`, `admin_sent_at`);

-- [2] Trigger status selesai untuk alur bot baru
DROP TRIGGER IF EXISTS `trg_user_progress_completed_at_insert`;
DROP TRIGGER IF EXISTS `trg_user_progress_completed_at`;

DELIMITER $$
CREATE TRIGGER `trg_user_progress_completed_at_insert`
BEFORE INSERT ON `user_progress`
FOR EACH ROW
BEGIN
    IF NEW.`current_step` >= 6 AND NEW.`completed_at` IS NULL THEN
        SET NEW.`completed_at` = CURRENT_TIMESTAMP;
    END IF;
END$$

CREATE TRIGGER `trg_user_progress_completed_at`
BEFORE UPDATE ON `user_progress`
FOR EACH ROW
BEGIN
    IF NEW.`current_step` >= 6
       AND OLD.`current_step` < 6
       AND NEW.`completed_at` IS NULL THEN
        SET NEW.`completed_at` = CURRENT_TIMESTAMP;
    END IF;
END$$
DELIMITER ;

